const item = $input.first().json;
let rawText = '';
if (item.output && Array.isArray(item.output) && item.output[0] && item.output[0].content) {
  const ct = item.output[0].content[0] && item.output[0].content[0].text;
  rawText = (typeof ct === 'object' && ct !== null) ? JSON.stringify(ct) : String(ct || '');
}
if (!rawText && typeof item.output === 'string') { rawText = item.output; }
if (!rawText && item.text) { rawText = String(item.text); }
if (!rawText && item.message && item.message.content) { rawText = String(item.message.content); }
rawText = rawText.trim();
const tick3 = String.fromCharCode(96,96,96);
if (rawText.startsWith(tick3)) {
  const nl = rawText.indexOf(10); rawText = rawText.slice(nl + 1);
  const lt = rawText.lastIndexOf(tick3); if (lt !== -1) rawText = rawText.slice(0, lt);
  rawText = rawText.trim();
}
let parsed = null;
try { parsed = JSON.parse(rawText); } catch(e) {}
if (!parsed) {
  const s = rawText.indexOf('{'); const e2 = rawText.lastIndexOf('}');
  if (s !== -1 && e2 !== -1) { try { parsed = JSON.parse(rawText.substring(s, e2+1)); } catch(e) {} }
}
if (!parsed) { parsed = { knowledgeLevel: 50, coverageLevel: 50, understandingLevel: 50, confidence: 50, feedback: 'Odpowiedz zostala zapisana.', strengthSignals: [], gapSignals: [], misconceptions: [], nextLearningStep: '' }; }
const body = $('Webhook — Przyjmij Odpowiedź').first().json.body;
const answerId = 'answer_' + body.studentId + '_' + body.taskId + '_' + body.questionIndex + '_' + Date.now();
return [{ json: {
  answerId, taskId: body.taskId, studentId: body.studentId,
  lessonId: body.lessonId, questionIndex: parseInt(body.questionIndex || 0),
  question: body.question, answerText: body.answer,
  knowledgeLevel: parsed.knowledgeLevel || 0, coverageLevel: parsed.coverageLevel || 0,
  understandingLevel: parsed.understandingLevel || 0, confidence: parsed.confidence || 0,
  feedback: parsed.feedback || '',
  strengthSignals: Array.isArray(parsed.strengthSignals) ? parsed.strengthSignals : [],
  gapSignals: Array.isArray(parsed.gapSignals) ? parsed.gapSignals : [],
  misconceptions: Array.isArray(parsed.misconceptions) ? parsed.misconceptions : [],
  nextLearningStep: parsed.nextLearningStep || '',
  evaluatedAt: new Date().toISOString()
}}];

const d = $input.first().json;
const toFSArr = function(arr) { return { arrayValue: { values: arr.map(function(s) { return { stringValue: String(s) }; }) } }; };
const body = JSON.stringify({ fields: {
  answerId: { stringValue: d.answerId }, taskId: { stringValue: d.taskId },
  studentId: { stringValue: d.studentId }, lessonId: { stringValue: d.lessonId },
  questionIndex: { integerValue: String(d.questionIndex) }, content: { stringValue: d.answerText },
  question: { stringValue: d.question }, knowledgeLevel: { integerValue: String(d.knowledgeLevel) },
  coverageLevel: { integerValue: String(d.coverageLevel) }, understandingLevel: { integerValue: String(d.understandingLevel) },
  confidence: { integerValue: String(d.confidence) }, feedback: { stringValue: d.feedback },
  strengthSignals: toFSArr(d.strengthSignals), gapSignals: toFSArr(d.gapSignals),
  misconceptions: toFSArr(d.misconceptions), nextLearningStep: { stringValue: d.nextLearningStep },
  evaluatedAt: { stringValue: d.evaluatedAt }
}});
return [{ json: { ...d, firestoreBody: body } }];

const taskDoc = $input.first().json;
const gradeData = $('Parsuj Ocenę Jakościową').first().json;
const totalQuestions = taskDoc.fields?.questions?.arrayValue?.values?.length || 4;
const currentAnswered = parseInt(taskDoc.fields?.answeredCount?.integerValue || '0') + 1;
const quizCompleted = currentAnswered >= totalQuestions;
return [{ json: {
  taskId: gradeData.taskId, studentId: gradeData.studentId,
  lessonId: gradeData.lessonId, classId: taskDoc.fields?.classId?.stringValue || '',
  answeredCount: currentAnswered, totalQuestions, quizCompleted,
  newStatus: quizCompleted ? 'done' : 'in_progress',
  newQuizStatus: quizCompleted ? 'completed' : 'in_progress',
  knowledgeLevel: gradeData.knowledgeLevel, coverageLevel: gradeData.coverageLevel,
  understandingLevel: gradeData.understandingLevel, confidence: gradeData.confidence,
  feedback: gradeData.feedback, nextLearningStep: gradeData.nextLearningStep
}}];

const d = $input.first().json;
const body = JSON.stringify({ fields: {
  status: { stringValue: d.newStatus }, quizStatus: { stringValue: d.newQuizStatus },
  answeredCount: { integerValue: String(d.answeredCount) },
  noteUnlocked: { booleanValue: d.quizCompleted }, exercisesUnlocked: { booleanValue: d.quizCompleted }
}});
return [{ json: { ...d, firestoreTaskBody: body } }];

